import json, math
from picosvg.svg_types import SVGPath
from picosvg.svg_transform import Affine2D
sol=json.load(open('package/icons.json'))['icons']
G='<g fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5">'
def g(*parts): return G+''.join(parts)+'</g>'
def p(d, extra=''): return f'<path {extra}d="{d}"/>'
def dot(x,y): return p(f'M{x} {y}H{x+0.0001}')
def tf(d, t): return SVGPath(d=d).absolute().apply_transform(t).d
def M(rot=0, sx=1, sy=1, pivot=(0,0), to=(0,0)):
    c,s_=math.cos(math.radians(rot)),math.sin(math.radians(rot))
    a,b,cc,dd=c*sx, s_*sx, -s_*sy, c*sy
    px,py=pivot; e=to[0]-(a*px+cc*py); f=to[1]-(b*px+dd*py)
    return Affine2D(a,b,cc,dd,e,f)
def rrect(x,y,w,h,r): return f'M{x+r} {y}H{x+w-r}A{r} {r} 0 0 1 {x+w} {y+r}V{y+h-r}A{r} {r} 0 0 1 {x+w-r} {y+h}H{x+r}A{r} {r} 0 0 1 {x} {y+h-r}V{y+r}A{r} {r} 0 0 1 {x+r} {y}Z'
CAL='M2 12C2 8.22876 2 6.34315 3.17157 5.17157C4.34315 4 6.22876 4 10 4H14C17.7712 4 19.6569 4 20.8284 5.17157C22 6.34315 22 8.22876 22 12V14C22 17.7712 22 19.6569 20.8284 20.8284C19.6569 22 17.7712 22 14 22H10C6.22876 22 4.34315 22 3.17157 20.8284C2 19.6569 2 17.7712 2 14V12Z'
calbase=[p(CAL),p('M7 4V2.5'),p('M17 4V2.5'),p('M2.5 9H21.5')]
out={}
out['calendar-check']=g(*calbase,p('M13.75 16.25L15.25 17.75L18.25 14.75'))
out['calendar-minus']=g(*calbase,p('M14 16H18'))
out['calendar-warning']=g(*calbase,p('M16 13.75V16.25'),dot(16,18.5))
out['user-warning']=g('<circle cx="12" cy="6" r="4"/>',
  p('M21 18C21 20.2091 19.2091 22 17 22C15.8869 22 14.8799 21.5453 14.1548 20.8115C13.4408 20.089 13 19.096 13 18C13 15.8976 14.6221 14.174 16.683 14.0124C16.7876 14.0042 16.8933 14 17 14C19.2091 14 21 15.7909 21 18Z'),
  p('M16.683 14.0124C15.4431 13.3838 13.8093 13.0019 12.019 13.0019C8.14253 13.0019 5 14.7924 5 17.001C5 19.2096 8.14253 21 12.019 21C12.7637 21 13.4813 20.9339 14.1548 20.8115'),
  p('M17 15.9V18.1'),dot(17,20))
# --- sports ---
out['jump-rope']=g(p(rrect(3.5,14,3,7.5,1.5)),p(rrect(17.5,14,3,7.5,1.5)),p('M5 14V10C5 6.13401 8.13401 3 12 3C15.866 3 19 6.13401 19 10V14'))
out['taichi']=g('<circle cx="12" cy="12" r="10"/>',p('M12 2C14.7614 2 17 4.23858 17 7C17 9.76142 14.7614 12 12 12C9.23858 12 7 14.2386 7 17C7 19.7614 9.23858 22 12 22'),dot(12,7),dot(12,17))
out['martial-arts']=g(p('M2 7.5H9.5M14.5 7.5H22M2 11.5H9.5M14.5 11.5H22'),p(rrect(9.5,5.5,5,8,1.75)),p('M10.75 13.5L8.25 20.25C8.1 20.66 8.45 21.08 8.88 21L10.2 20.75C10.47 20.7 10.7 20.52 10.8 20.26L12 17'),p('M13.25 13.5L15.75 20.25C15.9 20.66 15.55 21.08 15.12 21L13.8 20.75C13.53 20.7 13.3 20.52 13.2 20.26L12 17'))
out['fencing']=g(p('M7 17L21 3'),p('M3 21L5.5 18.5'),p('M3.75 15.5C5.4 15.9 8.1 18.6 8.5 20.25'),p('M17 17L3 3'),p('M21 21L18.5 18.5'),p('M20.25 15.5C18.6 15.9 15.9 18.6 15.5 20.25'))
head='M16.5 9.5C16.5 13.366 13.366 16.5 9.5 16.5C5.63401 16.5 2.5 13.366 2.5 9.5C2.5 5.63401 5.63401 2.5 9.5 2.5C13.366 2.5 16.5 5.63401 16.5 9.5Z'
handle=tf(rrect(-1.25,0,2.5,7.5,1.25), M(-45,1,1,(0,0),(14.6,14.6)))
out['padel']=g(p(head),p(handle),dot(9.5,9.5),dot(6.75,9.5),dot(12.25,9.5),dot(9.5,6.75),dot(9.5,12.25),dot(7.5,7.5),dot(11.5,7.5),dot(7.5,11.5),dot(11.5,11.5))
thead='M20 10C20 14.1421 16.6421 17.5 12.5 17.5C8.35786 17.5 5 14.1421 5 10C5 5.85786 8.35786 2.5 12.5 2.5C16.6421 2.5 20 5.85786 20 10Z'
th=tf(rrect(-1.25,0,2.5,6.5,1.25), M(45,1,1,(0,0),(7.4,15.1)))
out['table-tennis']=g(p(thead),p(th),'<circle cx="18.5" cy="19.5" r="2"/>')
out['badminton']=g(p('M9 17.5H15V18.5C15 20.1569 13.6569 21.5 12 21.5C10.3431 21.5 9 20.1569 9 18.5V17.5Z'),p('M9 17.5L5.5 3.5M15 17.5L18.5 3.5M11 17.5L10 3M13 17.5L14 3'),p('M5.5 3.5C7.5 2.8 16.5 2.8 18.5 3.5'),p('M7.4 11H16.6'))
holes=''.join(f'<circle cx="{12+5.5*math.cos(math.radians(k*60+30)):.3f}" cy="{12+5.5*math.sin(math.radians(k*60+30)):.3f}" r="1.25"/>' for k in range(6))
out['pickleball']=g('<circle cx="12" cy="12" r="10"/>','<circle cx="12" cy="12" r="1.25"/>',holes)
out['frisbee']=g('<ellipse cx="12" cy="10.5" rx="10" ry="4.5"/>',p('M2 10.5V12.5C2 14.9853 6.47715 17 12 17C17.5228 17 22 14.9853 22 12.5V10.5'),'<ellipse cx="12" cy="10.25" rx="5.5" ry="2"/>')
out['spikeball']=g('<ellipse cx="12" cy="12.5" rx="10" ry="3.5"/>','<ellipse cx="12" cy="12.5" rx="6" ry="1.75"/>',p('M4 14.6V19M20 14.6V19M12 16V21'),'<circle cx="12" cy="4.5" r="2"/>')
out['carabiner']=g(p('M17.5 7.5C17.5 4.73858 15.2614 2.5 12.5 2.5H11C8.79086 2.5 7 4.29086 7 6.5V17.5C7 19.7091 8.79086 21.5 11 21.5H12.5C14.3 21.5 15.8 20.2 16.1 18.4L16.6 15.5'),p('M14.1 6.5L12.9 16.6'),p('M17.5 7.5L16.9 12.25'))
out['boulder']=g(p('M2 21H22'),p('M3.5 21L6.3 11.2C6.7 9.8 7.6 8.6 8.9 7.8L12.6 5.5C14.2 4.5 16.3 5 17.3 6.6L20.2 11.4C20.7 12.2 21 13.2 21 14.2V21'),'<circle cx="10" cy="11" r="1"/>','<circle cx="15" cy="9.5" r="1"/>','<circle cx="12.5" cy="15.5" r="1"/>','<circle cx="17" cy="14.5" r="1"/>')
out['horseshoe']=g(p('M5 3V11C5 16.5228 8.13401 21 12 21C15.866 21 19 16.5228 19 11V3H15V11C15 14.866 13.6569 17 12 17C10.3431 17 9 14.866 9 11V3H5Z'),dot(7,6.5),dot(7,10.5),dot(8,14.75),dot(17,6.5),dot(17,10.5),dot(16,14.75))

# redesigns
car='M16 6.5C16 4.29086 14.2091 2.5 12 2.5C9.79086 2.5 8 4.29086 8 6.5L7 17C7 19.7614 9.23858 22 12 22C14.7614 22 17 19.7614 17 17L16.8 15'
gate='M16.8 15L14.7 9.9'
top='M16 6.5L16.3 10.1'
R=M(20,1,1,(12,12.25),(12,12.25))
