out['jump-rope']=g(p(tf(rrect(-1.4,-3.5,2.8,7,1.4),M(-28,1,1,(0,0),(5,6)))),p(tf(rrect(-1.4,-3.5,2.8,7,1.4),M(28,1,1,(0,0),(19,6)))),
  p('M6.64 9.1C7 14.5 8.8 21 12 21C15.2 21 17 14.5 17.36 9.1'))
pad='M12 2C16.1421 2 19 4.9 19 8.75C19 11.3 17.85 13.2 15.9 14.55C14.85 15.28 14.15 16.05 13.9 17H10.1C9.85 16.05 9.15 15.28 8.1 14.55C6.15 13.2 5 11.3 5 8.75C5 4.9 7.85786 2 12 2Z'
PR=M(-30,1,1,(12,12),(12,12))
